def _validate_request(data, client_id):
    """Validate the values required to handle a request.

    An empty payload may be meaningful to ``process``, and falsey client IDs may
    be valid in some integrations, so only the unambiguous missing-value case
    is rejected here.
    """
    if data is None:
        raise ValueError("request data is required")
    if client_id is None:
        raise ValueError("client_id is required")


def handle_request(data, client_id):
    """Validate, rate-limit, and process an incoming API request."""
    _validate_request(data, client_id)

    is_within_rate_limit = check_rate_limit(client_id)
    if not is_within_rate_limit:
        raise RuntimeError("rate limit exceeded")

    return process(data)

